   "RF": "🎯 Roter Faden COA1, Block 2",
   "V3": "🎯 Unterrichtsvideo 24.11.2026, Bildschirmaufnahme 130251 (ca. 12:50–13:02)",
   "V2": "🎯 Unterrichtsvideo 24.11.2026, Bildschirmaufnahme 111935 (ca. 10:43–11:19)",
   "V1": "🎯 Unterrichtsvideo 24.11.2026, (ca. 09:05–10:41), Standbild 01:34:00 (Unterrichtsdokument )",
